command_line:
set +e
cat > httpfile.wdl <<'EOF'
version 1.0
workflow httpfile {
  input { File f }
  call inspect { input: f = f }
  output { String first = inspect.first }
}
task inspect {
  input { File f }
  command <<<
    head -1 ~{f} > first.txt
  >>>
  output { String first = read_string("first.txt") }
}
EOF
cat > inputs.json <<'EOF'
{"httpfile.f":"https://storage.googleapis.com/encode-pipeline-genome-data/genome_tsv/v4/hg38.tsv"}
EOF
java -Dconfig.file=/dev/null -jar "/jetstream2/scratch/main/jobs/79144346/inputs/dataset_2ac0cb03-4620-4750-91ad-0e47d0ba0137.dat" run httpfile.wdl -i inputs.json > cromwell.stdout 2> cromwell.stderr
{
  echo '--- stdout tail ---'
  tail -120 cromwell.stdout
  echo '--- stderr ---'
  sed -n '1,200p' cromwell.stderr
} > probe.txt
exit 0
